export const BODY: string = "\n<p>تصویر میٹا ڈیٹا دیکھنا تکنیکی لگتا ہے، مگر اس میں ایک منٹ سے کم لگتا ہے۔ آپ ویور میں تصویر کھولتے ہیں، رپورٹ پڑھتے ہیں، اور فیصلہ کرتے ہیں کہ اس میں کچھ نجی رہنا چاہیے یا نہیں۔</p>\n<p>یہ رہنما مفت <a href=\"/ur/tasveer-metadata-dekhein/\">Image Metadata Viewer</a> کے ساتھ ہر مرحلہ بتاتا ہے۔ یہ آپ کے براؤزر میں کام کرتا ہے، اکاؤنٹ نہیں چاہیے، اور آپ کی تصویریں کبھی اپ لوڈ نہیں ہوتیں۔</p>\n<p>آخر تک آپ جان جائیں گے کہ GPS کوآرڈینیٹ کیسے ڈھونڈیں، کیمرہ ترتیبات کیسے پڑھیں، JSON رپورٹ کیسے برآمد کریں، اور جانچیں کہ صاف شدہ فائل واقعی صاف ہے۔</p>\n<h2 id=\"what-you-need\">شروع کرنے سے پہلے آپ کو کیا چاہیے</h2>\n<p>آپ کو خود تصویر فائل چاہیے، اپنے آلے پر محفوظ۔ آپ کے کیمرہ رول یا کیمرہ کارڈ کی اصل فائل سب سے زیادہ میٹا ڈیٹا رکھتی ہے۔</p>\n<p>واٹس ایپ، انسٹاگرام یا فیس بک سے ڈاؤن لوڈ شدہ تصویر خراب آزمائشی موضوع ہے۔ وہ خدمات اپ لوڈ پر EXIF اور GPS ہیڈر ہٹا دیتی ہیں، اس لیے ویور کو کم یا کچھ نہیں ملے گا۔</p>\n<p>اسکرین شاٹ بھی خراب آزمائشی موضوع ہیں۔ آپ کے آپریٹنگ سسٹم کا کلپ بورڈ خام پکسل منتقل کرتا ہے، اصل کیمرہ فائل نہیں، اس لیے چسپاں شدہ اسکرین شاٹ صرف ابعاد اور فارمیٹ دکھاتے ہیں۔</p>\n<h2 id=\"step-1-open-the-viewer\">مرحلہ 1: ویور کھولیں</h2>\n<p><a href=\"/ur/tasveer-metadata-dekhein/\">Image Metadata Viewer</a> صفحے پر جائیں۔ آپ کو اپ لوڈ والا حصہ اور ٹول کیا کرتا ہے، اس کی مختصر وضاحت دکھائی دے گی۔</p>\n<p>سائن ان اسکرین نہیں ہے اور پے وال نہیں ہے۔ ٹول مفت ہے، اور آپ جتنی چاہیں تصویریں ایک ایک کر کے جانچ سکتے ہیں۔</p>\n<p>اگر آپ فون پر ہیں تو صفحہ موبائل سفاری یا کروم میں کھولیں۔ لے آؤٹ ڈھل جاتا ہے، اور آپ اپنے کیمرہ رول سے سیدھی تصویر چن سکتے ہیں۔</p>\n<h2 id=\"step-2-upload-your-image\">مرحلہ 2: اپنی تصویر اپ لوڈ کریں</h2>\n<p>اپنی تصویر اپ لوڈ والے حصے پر گھسیٹ دیں، یا اپنے آلے سے فائل چننے کے لیے اس پر کلک کریں۔ فائل آپ کے براؤزر میں فوراً تجزیہ ہوتی ہے۔</p>\n<p>آپ ونڈوز پر Ctrl+V یا میک پر Cmd+V سے تصویر چسپاں بھی کر سکتے ہیں۔ چسپاں کرنا کلپ بورڈ پر پہلے سے موجود تصویر کے لیے مفید ہے، مگر یاد رکھیں کہ کلپ بورڈ تصویریں کوئی کیمرہ ہیڈر نہیں رکھتیں۔</p>\n<p>تجزیہ File ArrayBuffer بائٹ تجزیہ سے مقامی طور پر ہوتا ہے۔ صفر بائٹ آپ کے کمپیوٹر یا فون سے جاتے ہیں، جو رازداری ٹول کا پورا مقصد ہے۔</p>\n<h2 id=\"step-3-read-the-summary\">مرحلہ 3: خلاصہ اور رازداری بینر پڑھیں</h2>\n<p>خلاصہ بار پائے گئے کنٹینر فارمیٹ، پکسل ابعاد اور فائل سائز دکھاتا ہے۔ یہ یہ بھی بتاتا ہے کہ حساس ایمبیڈ شدہ میٹا ڈیٹا ٹیگ قسمیں ملیں یا نہیں۔</p>\n<p>پہلے فارمیٹ پڑھیں۔ ویور فائل نام پر بھروسے کی بجائے اصل بائنری میجک بائٹ جانچتا ہے، اس لیے .jpg ایکسٹینشن والی PNG پھر بھی PNG کے طور پر رپورٹ ہوتی ہے۔</p>\n<p>اگلا، رازداری خطرہ بینر پڑھیں۔ اگر حساس ٹیگ ملے تو بینر صاف کہتا ہے۔ اگر کچھ حساس نہ ملا تو بینر وہ بھی کہتا ہے۔</p>\n<h2 id=\"step-4-check-gps\">مرحلہ 4: GPS مقام انتباہ جانچیں</h2>\n<p>GPS کوآرڈینیٹ پہلی چیز ہیں جنہیں جانچنا چاہیے، کیونکہ وہ سب سے حساس فیلڈ ہیں جو تصویر رکھ سکتی ہے۔ پراپرٹی جدول کے بالکل اوپر انتباہ حصے تک اسکرول کریں۔</p>\n<p>اگر GPSIFD ٹیگ موجود ہوں تو کہری بینر پڑھتا ہے GPS Location Coordinates Detected۔ یہ اعشاریہ شکل میں بالکل ڈی کوڈ شدہ عرض البلد اور طول البلد دکھاتا ہے۔</p>\n<p>وہ دو عدد گھر، اسکول، کام کی جگہ، یا بالکل وہ جگہ اشارہ کر سکتے ہیں جہاں تصویر لی گئی تھی۔ انہیں نجی سمجھیں جب تک آپ دوسری صورت فیصلہ نہ کریں۔</p>\n<h2 id=\"step-5-read-the-table\">مرحلہ 5: میٹا ڈیٹا جدول پڑھیں</h2>\n<p>بینر کے نیچے نکالا گیا میٹا ڈیٹا جدول ہے۔ اندراج گروپ شدہ ہیں تاکہ آپ ہر لکیر پڑھے بغیر انہیں اسکین کر سکیں۔</p>\n<p>Camera گروپ میں بنانے والا، ماڈل، لینز اور سافٹ ویئر ہیں۔ EXIF گروپ میں شٹر رفتار، یپرچر، ISO، فوکل لمبائی، فلیش اور میٹرنگ موڈ ہیں۔</p>\n<p>GPS گروپ میں عرض البلد، طول البلد اور اونچائی ہیں جب موجود ہوں۔ PNG یا WebP حصے گروپ میں IHDR، pHYs، متن حصے اور VP8X جھنڈے ہیں۔</p>\n<h2 id=\"step-6-export-json\">مرحلہ 6: JSON رپورٹ کاپی یا برآمد کریں</h2>\n<p>اگر آپ کو فائل میں کیا تھا، اس کا ریکارڈ چاہیے تو اسے برآمد کریں۔ خلاصہ بار میں Copy JSON پر کلک کریں تاکہ مکمل ساختہ رپورٹ آپ کے کلپ بورڈ پر آ جائے۔</p>\n<p>Export JSON پر کلک کریں تاکہ آپ کی تصویر کے نام والی فائل _metadata لاحقہ کے ساتھ ڈاؤن لوڈ ہو۔ فائل صاف JSON رپورٹ ہے جسے آپ رکھ سکتے ہیں، ٹکٹ سے منسلک کر سکتے ہیں، یا بعد میں موازنہ کر سکتے ہیں۔</p>\n<p>ہر فیلڈ کا مطلب کیا ہے، اس کی گہری وضاحت کے لیے <a href=\"/ur/blog/exif-data-wazahat/\">EXIF Data Explained: What Your Photos Reveal</a> پڑھیں۔ ٹول کا مکمل جائزہ کے لیے <a href=\"/ur/blog/tasveer-metadata-viewer-rehnumai/\">Image Metadata Viewer: Complete Guide</a> دیکھیں۔</p>\n<h2 id=\"step-7-verify-clean\">مرحلہ 7: صاف شدہ فائل کی تصدیق کریں</h2>\n<p>تصویر سے میٹا ڈیٹا ہٹانے کے بعد صاف شدہ آؤٹ پٹ کو ویور میں واپس ڈالیں۔ یہ دوسری جانچ ثابت کرتی ہے کہ صفائی کام کی۔</p>\n<p>اگر صفائی کامیاب ہوئی تو سبز بینر تصدیق کرتا ہے کہ کوئی EXIF، GPS یا چھپے کیمرہ ٹیگ نہیں ملے۔ کوئی GPS انتباہ نہیں دکھائی دیتا۔</p>\n<p>اگر ٹیگ باقی رہیں تو جدول بالکل دکھاتا ہے کہ کون سے بچ گئے۔ عام بچ جانے والے PNG متن حصے اور JPEG تبصرے ہیں، جو کچھ صاف کرنے والے چھوڑ دیتے ہیں۔</p>\n<h2 id=\"viewing-on-mobile\">فون پر میٹا ڈیٹا دیکھنا</h2>\n<p>زیادہ تر تصویریں فون پر رہتی ہیں، اور جانچ پوسٹ کرنے سے ٹھیک پہلے سب سے اہم ہے۔ ویور موبائل سفاری یا کروم میں کھولیں اور اپنے کیمرہ رول سے تصویر چنیں۔</p>\n<p>خلاصہ، GPS انتباہ اور گروپ شدہ جدول، سب ڈیسک ٹاپ کی طرح دکھائی دیتے ہیں۔ Copy JSON اور Strip Metadata بھی اسی طرح کام کرتے ہیں۔</p>\n<p>سوشل ایپ کھولنے سے پہلے تصویر جانچیں، بعد میں نہیں۔ ایک بار تصویر پوسٹ ہو جائے تو کوئی بھی اسے ڈاؤن لوڈ کر سکتا ہے اور جو کچھ اس میں باقی ہے، وہ پڑھ سکتا ہے۔</p>\n<h2 id=\"reading-camera-settings\">رپورٹ میں کیمرہ ترتیبات کیسے پڑھیں</h2>\n<p>کیمرہ ترتیبات بتاتی ہیں کہ تصویر کیسے بنی۔ ہر فیلڈ کا سادہ مطلب ہے جب آپ جان لیں کہ کیا ڈھونڈنا ہے۔</p>\n<p>ISO سینسر حساسیت ہے۔ کم ISO کا مطلب روشن منظر یا ٹرائی پوڈ ہے؛ زیادہ ISO کا مطلب گہرا منظر اور عام طور پر زیادہ دانہ ہے۔</p>\n<p>یپرچر، F-عدد کے طور پر دکھایا گیا، یہ ہے کہ لینز کتنا کھلا۔ چھوٹا F-عدد کا مطلب چوڑا کھلنا اور دھندلا پس منظر ہے؛ بڑا کا مطلب گہرا، تیز منظر ہے۔</p>\n<h2 id=\"troubleshooting\">مسئلہ حل کرنا: جب رپورٹ خالی لگے</h2>\n<p>خالی رپورٹ کی عام طور پر سادہ وجہ ہوتی ہے۔ ویور ٹوٹا ہوا ماننے سے پہلے نیچے کی فہرست سے کام کریں۔</p>\n<ul>\n<li>تصویر واٹس ایپ، انسٹاگرام یا فیس بک سے آئی۔ یہ خدمات اپ لوڈ پر EXIF اور GPS ہٹا دیتی ہیں، اس لیے فائل صاف آتی ہے۔</li>\n<li>آپ نے اسکرین شاٹ چسپاں کیا۔ کلپ بورڈ خام پکسل منتقل کرتے ہیں، اس لیے چسپاں شدہ تصویریں کوئی کیمرہ ہیڈر نہیں رکھتیں۔</li>\n<li>فائل HEIC، GIF، BMP یا SVG ہے۔ ویور ان کے لیے کنٹینر معلومات اور ابعاد رپورٹ کرتا ہے، مگر مکمل بائنری EXIF حصے صرف JPEG، PNG اور WebP کے لیے نکالے جاتے ہیں۔</li>\n<li>تصویر ترمیم اور دوبارہ برآمد کی گئی۔ کئی ایڈیٹر برآمد پر EXIF چھوڑ دیتے ہیں جب تک آپ انہیں رکھنے کو نہ کہیں۔</li>\n<li>فائل پہلے سے صاف کی گئی تھی۔ Remove Image Metadata ٹول سے ہٹائی گئی تصویر سبز بغیر ٹیگ بینر دکھائے گی، جو درست نتیجہ ہے۔</li>\n</ul>\n<p>اگر آپ کو کیمرہ ڈیٹا کی توقع تھی اور کچھ نہ ملا تو کیمرہ رول سے سیدھا تازہ اصل سے آزمائیں۔ اس سے معلوم ہوتا ہے کہ وجہ فائل ہے یا ویور۔</p>\n<p>اگر اصل بھی کچھ نہ دکھائے تو اپنے کیمرہ ایپ ترتیبات جانچیں۔ کچھ فون آپ کو مقام ریکارڈنگ بند کرنے دیتے ہیں، جو GPS ٹیگ ماخذ پر ہٹا دیتا ہے۔</p>\n<h2 id=\"common-mistakes\">بچنے والی عام غلطیاں</h2>\n<p>سب سے عام غلطی غلط فائل جانچنا ہے۔ لوگ پہلے سے پوسٹ شدہ کاپی جانچتے ہیں، کچھ نہیں دیکھتے، اور مان لیتے ہیں کہ اصل بھی صاف ہے۔ ہمیشہ وہ فائل جانچیں جسے آپ شیئر کرنے والے ہیں۔</p>\n<p>دوسری غلطی فائل نام پر بھروسہ کرنا ہے۔ .jpg فائل واقعی PNG ہو سکتی ہے، اور ویور میجک بائٹ سے صحیح فارمیٹ رپورٹ کرتا ہے۔ خلاصہ پڑھیں، ایکسٹینشن نہیں۔</p>\n<p>تیسری غلطی دوسری جانچ چھوڑنا ہے۔ ڈاؤن لوڈ دکھائی دینے پر ہٹانا مکمل لگتا ہے، مگر صرف دوبارہ جانچ ثابت کرتی ہے کہ ٹیگ گئے۔</p>\n<h2 id=\"comparing-photos\">دو تصویروں کا ساتھ ساتھ موازنہ کرنا</h2>\n<p>کبھی ایک رپورٹ کافی نہیں ہوتی۔ دو تصویروں کا موازنہ دکھاتا ہے کہ ان کے درمیان کیا بدلا، جو اس وقت مفید ہے جب فائل کئی ایپس سے گزرے۔</p>\n<p>پہلی تصویر کھولیں، اس کی JSON رپورٹ برآمد کریں، اور فائل محفوظ کریں۔ پھر خلاصہ بار میں سرخ کوڑے دان آئیکن سے ویور صاف کریں اور دوسری تصویر اسی طرح کھولیں۔</p>\n<p>دو JSON رپورٹ ساتھ ساتھ رکھیں۔ کوئی بھی فیلڈ جو ایک میں موجود اور دوسری میں گم ہو، اسے درمیان میں پروسیس کرنے والی چیز نے شامل یا ہٹایا۔</p>\n<h2 id=\"saving-reports\">بعد کے لیے رپورٹ محفوظ کرنا</h2>\n<p>برآمد شدہ JSON رپورٹ رکھنے کے قابل ہیں جب تصویر اہم ہو۔ رپورٹ چھوٹی متن فائل ہے، تصویر کے ساتھ یا پراجیکٹ فولڈر میں محفوظ کرنا آسان ہے۔</p>\n<p>کلائنٹ کام کے لیے رپورٹ رکھیں، جہاں کلائنٹ پوچھ سکتا ہے کہ تصویر کب اور کہاں لی گئی۔ JSON اس سوال کا جواب دیتا ہے بغیر اصل فائل شیئر کیے۔</p>\n<p>انہیں ڈیبگ کے لیے بھی رکھیں۔ جب تصویر مہینوں بعد عجیب برتاؤ کرے تو محفوظ شدہ رپورٹ دکھاتی ہے کہ فائل میں مزید پروسیسنگ سے پہلے کیا تھا۔</p>\n<h2 id=\"how-to-view-summary\">فوری خلاصہ</h2>\n<p><a href=\"/ur/tasveer-metadata-dekhein/\">Image Metadata Viewer</a> کھولیں، اصل فائل ڈالیں، اور پہلے خلاصہ بینر پڑھیں۔ پھر GPS انتباہ جانچیں، گروپ شدہ جدول اسکین کریں، اور کوئی بھی کہری Privacy Tag لیبل نوٹ کریں۔</p>\n<p>اگر ریکارڈ چاہیے تو JSON برآمد کریں۔ اگر کچھ حساس دکھائی دے تو <a href=\"/ur/tasveer-metadata-hatayein/\">Remove Image Metadata</a> سے فائل ہٹائیں، پھر تصدیق کے لیے صاف شدہ کاپی دوبارہ جانچیں۔</p>\n<p>پورا معمول ایک منٹ سے کم لگتا ہے۔ اسے ہر عوامی پوسٹ سے پہلے عادت بنائیں، اور آپ کی تصویریں صرف وہی دکھائیں گی جو آپ نے شیئر کرنا چنا۔</p>\n";

